function greet(name) {
  return "Hello, " + name + "!";
}

function makeArray(a, b, c) {
  return [a, b, c];
}

function makeUser(name, age) {
  return { name, age, active: true };
}

function classify(score) {
  if (score >= 90) return "A";
  if (score >= 80) return "B";
  if (score >= 70) return "C";
  return "F";
}

function sum(arr) {
  let total = 0;
  for (const n of arr) {
    total += n;
  }
  return total;
}

function getDayName(day) {
  switch (day) {
    case 0: return "Sunday";
    case 1: return "Monday";
    case 2: return "Tuesday";
    case 3: return "Wednesday";
    case 4: return "Thursday";
    case 5: return "Friday";
    case 6: return "Saturday";
    default: return "Unknown";
  }
}

function doubleAll(arr) {
  return arr.map(n => n * 2);
}

function filterEvens(arr) {
  return arr.filter(n => n % 2 === 0);
}

function flatten(arrays) {
  return arrays.reduce((acc, arr) => acc.concat(arr), []);
}

function processNumbers(arr) {
  return arr
    .filter(n => n > 0)
    .map(n => n * n)
    .reduce((sum, n) => sum + n, 0);
}

function updateUser(user, updates) {
  return { ...user, ...updates, updatedAt: Date.now() };
}

function getFullName({ first, last, middle }) {
  if (middle) return first + " " + middle + " " + last;
  return first + " " + last;
}

function getDeepValue(obj) {
  return obj.a.b.c;
}

async function getValue(x) {
  return Promise.resolve(x);
}

async function fetchAll() {
  const [a, b] = await Promise.all([
    Promise.resolve(1),
    Promise.resolve(2)
  ]);
  return [a, b];
}

function safeDivide(a, b) {
  try {
    if (b === 0) throw new Error("Division by zero");
    return { success: true, value: a / b };
  } catch (e) {
    return { success: false, error: e.message };
  }
}

function createLookup(items) {
  const map = new Map();
  for (const item of items) {
    map.set(item.id, item);
  }
  return {
    found: map.get("a"),
    missing: map.get("z"),
    size: map.size
  };
}

function uniqueValues(arr) {
  const set = new Set(arr);
  return Array.from(set);
}

function processUsers(users) {
  return users
    .filter(u => u.active)
    .map(u => ({
      id: u.id,
      displayName: u.firstName + " " + u.lastName,
      role: u.isAdmin ? "admin" : "user"
    }))
    .sort((a, b) => a.displayName.localeCompare(b.displayName));
}

async function fetchWithRetry(url, maxRetries) {
  let lastError;
  for (let i = 0; i < maxRetries; i++) {
    try {
      const response = await Promise.resolve({ ok: true, data: "success" });
      if (response.ok) return { success: true, data: response.data };
    } catch (e) {
      lastError = e;
    }
  }
  return { success: false, error: "max retries exceeded" };
}

function processItems(items, transform, filter) {
  const result = [];
  for (const item of items) {
    if (filter(item)) {
      result.push(transform(item));
    }
  }
  return result;
}

function handleApiResponse(response) {
  if (!response) {
    return { status: "error", message: "No response" };
  }

  if (response.statusCode >= 200 && response.statusCode < 300) {
    return {
      status: "success",
      data: response.body,
      meta: {
        timestamp: Date.now(),
        requestId: response.headers["x-request-id"]
      }
    };
  }

  if (response.statusCode >= 400) {
    return {
      status: "error",
      code: response.statusCode,
      message: response.body?.error || "Unknown error"
    };
  }

  return { status: "unknown", code: response.statusCode };
}

function validateConfig(config) {
  const errors = [];

  if (!config.host || typeof config.host !== "string") {
    errors.push("host is required and must be a string");
  }

  if (config.port !== undefined) {
    if (typeof config.port !== "number" || config.port < 1 || config.port > 65535) {
      errors.push("port must be a number between 1 and 65535");
    }
  }

  if (config.debug !== undefined && typeof config.debug !== "boolean") {
    errors.push("debug must be a boolean");
  }

  return {
    valid: errors.length === 0,
    errors,
    config: errors.length === 0 ? config : undefined
  };
}

function createEventEmitter() {
  const listeners = new Map();

  return {
    on(event, fn) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event).push(fn);
      return () => this.off(event, fn);
    },
    off(event, fn) {
      const fns = listeners.get(event);
      if (fns) {
        const idx = fns.indexOf(fn);
        if (idx >= 0) fns.splice(idx, 1);
      }
    },
    emit(event, ...args) {
      const fns = listeners.get(event);
      if (fns) {
        for (const fn of fns) fn(...args);
      }
    }
  };
}
